-- Positive controls and denial checks run as real database roles, never service_role.
SELECT ok(c.relrowsecurity, c.relname || ' has RLS enabled') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('projects','contacts','interviews','learnings','experiments','outreach') ORDER BY c.relname;
SELECT ok(NOT rolbypassrls AND NOT rolsuper, rolname || ' cannot bypass RLS') FROM pg_roles WHERE rolname IN ('anon','authenticated') ORDER BY rolname;

RESET ROLE;
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE authenticated;
SELECT is(current_user::text, 'authenticated', 'owner_a uses actual authenticated database role');
SELECT is(auth.uid(), firstten_policy_test.id('owner_a'), 'owner_a has its own JWT subject');
SELECT is(firstten_policy_test.visible_count('projects',firstten_policy_test.id('project_a')),1::bigint,'owner can read projects');
SELECT is(firstten_policy_test.visible_count('projects',firstten_policy_test.id('project_b')),0::bigint,'owner cannot read another owner projects');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.projects SET name='Fixture changed' WHERE id=firstten_policy_test.id('project_b')$case$), 'ok:0', 'owner cannot update another owner projects');
SELECT is(firstten_policy_test.attempt($case$DELETE FROM public.projects WHERE id=firstten_policy_test.id('project_b')$case$), 'ok:0', 'owner cannot delete another owner projects');
SELECT is(firstten_policy_test.attempt($case$INSERT INTO public.projects(id,user_id,name) VALUES (gen_random_uuid(),firstten_policy_test.id('owner_b'),'Fixture create')$case$), 'error:42501', 'forged user_id is denied for projects');
SELECT is(firstten_policy_test.attempt($case$INSERT INTO public.projects(id,name) VALUES (firstten_policy_test.id('new_projects'),'Fixture create')$case$), 'ok:1', 'owner can insert projects using auth.uid default');
SELECT is((SELECT user_id FROM public.projects WHERE id=firstten_policy_test.id('new_projects')),auth.uid(),'inserted projects belongs to current actor');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.projects SET name='Fixture changed' WHERE id=firstten_policy_test.id('new_projects')$case$), 'ok:1', 'owner can update own projects');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.projects SET user_id=firstten_policy_test.id('owner_b') WHERE id=firstten_policy_test.id('new_projects')$case$), 'error:42501', 'owner cannot reassign user_id in projects');
SELECT is(firstten_policy_test.attempt($case$DELETE FROM public.projects WHERE id=firstten_policy_test.id('new_projects')$case$), 'ok:1', 'owner can delete own projects');
SELECT is(firstten_policy_test.visible_count('contacts',firstten_policy_test.id('contact_a')),1::bigint,'owner can read contacts');
